function e(e){if(!e)return null;let t=new Date(`${e}T23:59:59`);if(isNaN(t.getTime()))return null;let n=t.getTime()-Date.now();if(n<=0)return{closed:!0,urgent:!0,label:`Closed`,days:0};let r=Math.floor(n/864e5);if(r>=1)return{closed:!1,urgent:r<=5,label:`${r} day${r>1?`s`:``} left`,days:r};let i=Math.max(1,Math.floor(n/36e5));return{closed:!1,urgent:!0,label:`${i} hr${i>1?`s`:``} left`,days:0}}export{e as t};